class SpikeVariantProvider:
    """Provide Spike sequences independently of model training."""

    DEFAULT_VARIANTS = (
        "origin",
        "alpha",
        "beta",
        "gamma",
        "delta",
        "omicron",
        "omicron_ba1",
        "omicron_ba2",
    )

    def __init__(self, project_root: Path):
        self.project_root = Path(project_root)

    def get(self, name: str) -> str:
        providers = {
            "origin": lambda: ORIGIN_SPIKE_SEQUENCE,
            "alpha": test_data_gen_alpha,
            "beta": test_data_gen_beta,
            "gamma": test_data_gen_gamma,
            "delta": test_data_gen_delta,
            "omicron": test_data_gen_omicron,
            "omicron_ba1": test_data_gen_omicron_ba1,
            "omicron_ba2": test_data_gen_omicron_ba2,
            "omicron_ba3": test_data_gen_omicron_ba3,
            "omicron_jn1": self._from_project_root(test_data_gen_omicron_jn1),
            "omicron_eg5": self._from_project_root(test_data_gen_omicron_eg5),
            "omicron_kp3": self._from_project_root(test_data_gen_omicron_kp3),
            "omicron_xec": self._from_project_root(test_data_gen_omicron_xec),
        }
        try:
            return providers[name]()
        except KeyError as exc:
            raise KeyError(f"Unknown Spike variant: {name}") from exc

    def _from_project_root(self, func):
        def provider():
            # Legacy mutation functions use ./mutations relative paths.
            # Temporarily execute them with project_root as the working directory.
            import os
            old_cwd = Path.cwd()
            try:
                os.chdir(self.project_root)
                return func()
            finally:
                os.chdir(old_cwd)
        return provider
